<script setup lang="ts">
import { computed, onMounted, ref, shallowRef } from 'vue'
import { ElMessage } from 'element-plus'
import { ArrowLeft, Refresh, Location, Aim, Fold, Expand } from '@element-plus/icons-vue'
import { useRoute, useRouter } from 'vue-router'
import PotreeFrame from '@/components/PotreeFrame.vue'
import ScrollReveal from '@/components/ScrollReveal.vue'
import { createAnnotation, createMeasurement, getAnnotations, getMeasurements, getViewerConfig } from '@/api/viewer'
import { getCase } from '@/api/cases'
import type { Annotation, Measurement, Point3D } from '@/types/viewer'
const route=useRoute(),router=useRouter(),frame=ref<InstanceType<typeof PotreeFrame>>(),loading=ref(true),error=ref(''),manifestUrl=ref(''),versionId=ref(''),annotations=ref<Annotation[]>([]),measurements=ref<Measurement[]>([]),point=ref<Point3D>({x:0,y:0,z:0}),title=ref(''),forcedMasks=shallowRef<Array<{id:string;type:'HIDE';title:string;range:{min:[number,number,number];max:[number,number,number]};enforced:true}>>([]),mock=import.meta.env.VITE_USE_MOCK!=='false'
const panelOpen=ref(true),saving=ref(false),forcedCount=computed(()=>forcedMasks.value.length)
async function reload(){[annotations.value,measurements.value]=await Promise.all([getAnnotations(versionId.value),getMeasurements(versionId.value)])}
async function init(){try{const record=await getCase(String(route.params.caseId)),status=record.latestVersion?.status;if(status==='ARCHIVED')throw new Error('该教学版本已归档，不能进入三维工作台。');if(status!=='READY'&&status!=='PUBLISHED')throw new Error('该案例版本尚未就绪或未发布。');versionId.value=record.latestVersion!.id;const config=await getViewerConfig(versionId.value);manifestUrl.value=config.manifestUrl;forcedMasks.value=config.forcedDesensitizationRules.filter(rule=>rule.mode==='HIDE').map(rule=>({id:rule.id,type:'HIDE',title:rule.title,range:{min:rule.geometry.min,max:rule.geometry.max},enforced:true}));await reload()}catch(e){error.value=e instanceof Error?e.message:'工作台初始化失败'}finally{loading.value=false}}
async function savePoint(){if(saving.value)return;if(!title.value.trim())return ElMessage.warning('请输入标记标题');saving.value=true;try{await createAnnotation(versionId.value,{type:'POINT_MARK',geometry:{position:point.value},title:title.value,description:'',viewerState:{camera:{}}});title.value='';await reload();ElMessage.success('标记已保存')}catch(e){ElMessage.error(e instanceof Error?e.message:'标记保存失败')}finally{saving.value=false}}
async function saveMeasure(v:{startPoint:Point3D;endPoint:Point3D}){try{await createMeasurement(versionId.value,v);await reload();ElMessage.success('测距已保存')}catch(e){ElMessage.error(e instanceof Error?e.message:'测距保存失败')}}
onMounted(init)
</script>
<template><main class="viewer-workspace"><div class="viewer-stage"><PotreeFrame v-if="!loading&&!error" ref="frame" :manifest-url="manifestUrl" :mock="mock" :masks="forcedMasks" :hide-preview="true" @error="error=$event" @pick="point=$event" @measurement="saveMeasure"/></div><ScrollReveal immediate class="floating-top"><header class="viewer-toolbar"><el-button text :icon="ArrowLeft" @click="router.push(`/admin/cases/${route.params.caseId}`)">返回详情</el-button><div class="workspace-name"><strong>现场工作台</strong><span>点云浏览与标记</span></div><div class="tools"><el-button text :disabled="loading||!!error" :icon="Refresh" @click="frame?.resetView()">复位</el-button><el-button text :disabled="loading||!!error" :icon="Location" @click="panelOpen=true;frame?.startPointPick()">标记</el-button><el-button text :disabled="loading||!!error" :icon="Aim" @click="frame?.startMeasurement()">测距</el-button><el-button text :icon="panelOpen?Fold:Expand" :aria-expanded="panelOpen" @click="panelOpen=!panelOpen">{{panelOpen?'收起面板':'记录面板'}}</el-button></div></header></ScrollReveal><div v-if="loading" class="stage-message" role="status"><span class="status-dot"/>正在准备受控现场…</div><div v-else-if="error" class="stage-message error-message" role="alert"><h2>现场暂时无法打开</h2><p>{{error}}</p><el-button @click="router.go(0)">重新加载</el-button></div><div v-if="mock" class="mock-banner">模拟 Viewer 模式 · 未加载真实点云</div><div v-if="forcedCount" class="forced-banner" role="status"><strong>HIDE · 教学强制遮挡已生效</strong><span>{{forcedCount}} 个区域强制隐藏，不能关闭；遮挡不代表物理删除。</span></div><ScrollReveal v-if="panelOpen&&!loading&&!error" immediate class="floating-panel"><aside class="records-panel"><div class="panel-heading"><h2>现场记录</h2><el-tag size="small">{{annotations.length+measurements.length}} 条</el-tag></div><p class="panel-subtitle">选取点位，记录空间中的发现。</p><label for="mark-title">点位标记</label><el-input id="mark-title" v-model="title" placeholder="标记标题" @keyup.enter="savePoint"/><p class="coordinates">X {{point.x.toFixed(2)}} · Y {{point.y.toFixed(2)}} · Z {{point.z.toFixed(2)}}</p><el-button type="primary" :loading="saving" @click="savePoint">保存点标记</el-button><el-divider/><h3>标记列表</h3><p v-if="!annotations.length" class="empty">暂无标记。选择上方“标记”开始记录。</p><div v-for="item in annotations" :key="item.id" class="record"><span class="record-dot"/><div><strong>{{item.title}}</strong><p>{{item.description||'点位记录'}}</p></div></div><el-divider/><h3>测距列表</h3><p v-if="!measurements.length" class="empty">暂无测距。选择上方“测距”添加两点距离。</p><div v-for="item in measurements" :key="item.id" class="record"><span class="record-dot"/><strong>{{Math.hypot(item.startPoint.x-item.endPoint.x,item.startPoint.y-item.endPoint.y,item.startPoint.z-item.endPoint.z).toFixed(2)}} m</strong></div></aside></ScrollReveal></main></template>
