ine-height:1.8}.mock-banner{position:absolute;left:28px;bottom:38px;color:#c3a573;font-size:12px}.forced-banner{position:absolute;top:110px;left:24px;max-width:calc(100% - 375px);padding:14px 18px;border:1px solid #df9a3280;border-radius:12px;background:#2e2317f0;color:#ffce86;font-size:12px}.forced-banner span{display:block;margin-top:7px;line-height:1.6}.status-dot{display:inline-block;width:6px;height:6px;border-radius:50%;margin-right:10px;background:#8bb7a5}@media(max-width:700px){.floating-top{top:10px;left:10px;right:10px}.viewer-toolbar{flex-wrap:wrap;gap:8px;padding:10px}.workspace-name{margin-left:auto}.tools{width:100%;justify-content:space-between}.floating-panel{top:140px;right:12px;bottom:80px;width:min(300px,calc(100vw - 24px))}.forced-banner{top:auto;bottom:22px;left:12px;max-width:calc(100% - 24px);z-index:4}.mock-banner{left:16px;bottom:10px}.viewer-toolbar :deep(.el-button){font-size:12px}}@supports not (backdrop-filter:blur(1px)){.viewer-toolbar,.records-panel{background:#18181d}}
